const {chromium}=require(process.env.MDO_PLAYWRIGHT_PATH || 'playwright');
const assert=require('node:assert/strict');
(async()=>{
 const origin=process.argv[2],evidence=process.argv[3],browser=await chromium.launch({headless:true,channel:'msedge'});
 let page;const errors=[],diagnostics=[];
 try{
  page=await browser.newPage({viewport:{width:1440,height:1000},locale:'zh-CN'});
  page.on('pageerror',error=>errors.push(String(error)));page.on('dialog',dialog=>dialog.accept());
  page.on('console',message=>{if(['error','warning'].includes(message.type()))diagnostics.push(message.text());});
  page.on('requestfailed',request=>diagnostics.push([request.url(),request.failure()]));
  page.on('response',response=>{if(response.status()>=400)diagnostics.push([response.url(),response.status()]);});
  await page.route('**/*',route=>new URL(route.request().url()).hostname==='127.0.0.1'?route.continue():route.abort());
  await page.goto(origin+'/');await page.waitForFunction(()=>Boolean(window.mdo));await page.locator('#new-workbench-tab').click();
  await page.getByRole('heading',{name:'新标签页',exact:true}).waitFor();
  const fixture=await page.evaluate(async unicodePayload=>{
   const root=(await mdo.files.resolve({path:'file-fixture'})).path;
   if(!root.includes('workbench-ui-'))throw Error('File fixture escaped its private test directory');
   await mdo.files.mkdir({path:root});await mdo.files.mkdir({path:root+'/nested'});
   await mdo.files.write({path:root+'/primary.js',text:'const answer = 42;\nconsole.log(answer);\n'});
   await mdo.files.write({path:root+'/nested/second.md',text:'# Markdown fixture\n\n**Safe preview** <script>window.PWNED=true</script>\n'});
   await mdo.files.write({path:root+'/.hidden',text:'hidden'});
   await mdo.files.write({path:root+'/utf16.txt',base64:unicodePayload});
   const image=document.createElement('canvas');image.width=2;image.height=2;image.getContext('2d').fillRect(0,0,2,2);
   await mdo.files.write({path:root+'/pixel.png',base64:image.toDataURL('image/png').split(',')[1]});
   const long='line of log\n'.repeat(26000);await mdo.files.write({path:root+'/large.log',text:long});
   const panel=await mdo.panel.open({client:mdo.clientId,type:'mdo.files',key:'files',params:{root},reveal:'activate'});
   window.fileFixture={root,panel};return {root,id:panel.id};
  },Buffer.from('\ufeff原始\r\n内容\r\n','utf16le').toString('base64'));
  await page.getByRole('button',{name:'primary.js',exact:true}).click();
  await page.locator('.wb-source-text').filter({hasText:'const answer = 42;'}).waitFor();
  assert.ok(await page.locator('.wb-token-keyword').count()>0);
  const treeBefore=await page.locator('.wb-file-tree').boundingBox();await page.getByRole('separator',{name:'调整目录树宽度',exact:true}).focus();await page.keyboard.press('ArrowLeft');
  assert.ok((await page.locator('.wb-file-tree').boundingBox()).width>treeBefore.width);
  await page.locator('.wb-source').focus();await page.keyboard.press('Control+f');await page.getByRole('textbox',{name:'查找已加载内容',exact:true}).fill('answer');
  await page.locator('.wb-file-find').getByText('第 1 行',{exact:true}).waitFor();await page.keyboard.press('Escape');
  await page.getByRole('button',{name:'选择第 1 行',exact:true}).click();await page.getByRole('button',{name:'引用到对话',exact:true}).click();
  await page.getByRole('button',{name:'编辑文件',exact:true}).click();await page.locator('.wb-file-editor').fill('const answer = 43;\n');
  await page.getByRole('button',{name:'保存文件',exact:true}).evaluate(button=>button.click());
  await page.waitForFunction(()=>document.querySelector('[aria-label="保存文件"]')?.disabled===true);
  assert.equal(await page.evaluate(()=>mdo.files.read({path:window.fileFixture.root+'/primary.js'}).then(value=>value.text)),'const answer = 43;\n');
  await page.locator('.wb-file-editor').fill('const answer = 44; // draft\n');
  await page.evaluate(()=>mdo.files.write({path:window.fileFixture.root+'/primary.js',text:'external content\n'}));
  await page.getByRole('button',{name:'保存文件',exact:true}).click();
  await page.getByText('文件已被外部修改，编辑内容已保留。',{exact:true}).waitFor();
  assert.equal(await page.locator('.wb-file-editor').inputValue(),'const answer = 44; // draft\n');
  await page.getByRole('button',{name:'比较磁盘内容',exact:true}).click();
  await page.getByRole('dialog').waitFor();assert.equal(await page.getByRole('dialog').locator('textarea').nth(1).inputValue(),'external content\n');
  await page.getByRole('button',{name:'关闭比较',exact:true}).click();
  await page.reload();await page.waitForFunction(()=>Boolean(window.mdo));await page.locator('.wb-file-editor').waitFor({timeout:15000});
  assert.equal(await page.locator('.wb-file-editor').inputValue(),'const answer = 44; // draft\n');
  await page.screenshot({path:evidence+'/files-draft.png'});
  await page.getByRole('button',{name:'重新读取磁盘文件',exact:true}).click();
  await page.locator('.wb-source-text').filter({hasText:'external content'}).waitFor();
  assert.equal(await page.locator('.wb-file-editor').count(),0);
  await page.getByRole('textbox',{name:'搜索项目文件',exact:true}).fill('second');
  await page.getByRole('button',{name:'nested/second.md',exact:true}).click();
  await page.getByRole('button',{name:'切换 Markdown 预览',exact:true}).click();await page.getByRole('heading',{name:'Markdown fixture',exact:true}).waitFor();
  assert.equal(await page.evaluate(()=>window.PWNED),undefined);
  await page.getByRole('textbox',{name:'搜索项目文件',exact:true}).fill('utf16.txt');await page.getByRole('button',{name:'utf16.txt',exact:true}).click();
  await page.locator('.wb-source-text').filter({hasText:'原始'}).waitFor();
  await page.getByRole('button',{name:'编辑文件',exact:true}).click();await page.locator('.wb-file-editor').fill('修改 🌙\n内容\n');
  await page.getByRole('button',{name:'保存文件',exact:true}).click();await page.waitForFunction(()=>document.querySelector('[aria-label="保存文件"]')?.disabled===true);
  const unicodeSaved=await page.evaluate(path=>mdo.files.read({path}),fixture.root+'/utf16.txt');
  assert.equal(Buffer.from(unicodeSaved.base64,'base64').toString('utf16le'),'\ufeff修改 🌙\r\n内容\r\n');
  await page.getByRole('textbox',{name:'搜索项目文件',exact:true}).fill('pixel.png');await page.getByRole('button',{name:'pixel.png',exact:true}).click();
  await page.waitForFunction(()=>document.querySelector('.wb-file-image')?.naturalWidth===2);
  await page.getByRole('textbox',{name:'搜索项目文件',exact:true}).fill('large.log');await page.getByRole('button',{name:'large.log',exact:true}).click();
  await page.getByRole('button',{name:'继续加载文件',exact:true}).waitFor();await page.getByRole('button',{name:'继续加载文件',exact:true}).click();
  await page.waitForFunction(()=>!document.querySelector('[aria-label="继续加载文件"]'));
  assert.ok(await page.locator('.wb-source-line').count()<150,'source virtualization mounted too many rows');
  await page.locator('.wb-source').evaluate(node=>{node.scrollTop=node.scrollHeight;});
  await page.waitForFunction(()=>[...document.querySelectorAll('.wb-source-line')].some(node=>Number(node.dataset.line)>25000));
  await page.screenshot({path:evidence+'/files-desktop.png'});
  await page.setViewportSize({width:390,height:844});await page.waitForTimeout(500);
  require('node:fs').writeFileSync(evidence+'/mobile-layout.json',JSON.stringify(await page.evaluate(()=>({scroll:[scrollX,scrollY],view:document.querySelector('.wb-files-view')?.getBoundingClientRect().toJSON(),dock:document.querySelector('.workbench')?.getBoundingClientRect().toJSON(),shell:document.querySelector('#app-shell')?.getBoundingClientRect().toJSON(),width:innerWidth})),null,2));
  await page.screenshot({path:evidence+'/files-mobile.png'});
  const mobile=await page.locator('.wb-files-view').boundingBox();assert.ok(mobile.x>=-1&&mobile.width<=391&&mobile.width>300,JSON.stringify(mobile));
  assert.deepEqual(errors,[]);console.log('File workbench actual DOM: read/edit/save, conflicts, draft restart, safe Markdown, search, large-file paging and virtualization: PASS');
 }catch(error){console.error('Page errors:',errors,'Diagnostics:',diagnostics);require('node:fs').writeFileSync(evidence+'/failure-diagnostics.json',JSON.stringify({errors,diagnostics},null,2));if(page)await page.screenshot({path:evidence+'/failure.png'}).catch(()=>{});throw error;}
 finally{await browser.close();}
})().catch(error=>{console.error(error);process.exitCode=1;});
